-- Шаг 72: баннер «Удаление тату» (чанк banner-interial-category-new, шаблон 19) — фото справа (только экраны шире 1024 px) отдаётся
-- AVIF / WebP 720 и 1038 px (assets/templates/redesign/img/tz-banner-in-*, 27–142 КБ) вместо PNG ~1 МБ; на узких экранах не скачивается;
-- loading="eager" + fetchpriority="high" (на десктопе — главная картинка первого экрана). Повторный запуск ничего не меняет.
UPDATE Impulse_Digital_X_site_htmlsnippets SET snippet = REPLACE(snippet, '                <img src=\"/images/inner/banner-in.png\" alt=\"photo\">\n', '                {* фото справа (только экраны шире 1024 px — template.css): AVIF / WebP 720 и 1038 px вместо PNG ~1 МБ (шаг 72;\n                   картинки — assets/templates/redesign/img/tz-banner-in-*); на узких экранах — пустая 1×1, фото не скачивается;\n                   loading=\"eager\" — на десктопе это главная картинка первого экрана (без него плагин ставит loading=\"lazy\") *}\n                <picture>\n                    <source media=\"(max-width: 1024px)\" srcset=\"data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7\">\n                    <source type=\"image/avif\" srcset=\"/assets/templates/redesign/img/tz-banner-in-720.avif 720w, /assets/templates/redesign/img/tz-banner-in-1038.avif 1038w\" sizes=\"49vw\">\n                    <source type=\"image/webp\" srcset=\"/assets/templates/redesign/img/tz-banner-in-720.webp 720w, /assets/templates/redesign/img/tz-banner-in-1038.webp 1038w\" sizes=\"49vw\">\n                    <img src=\"/images/inner/banner-in.png\" alt=\"photo\" width=\"1038\" height=\"940\" loading=\"eager\" fetchpriority=\"high\" decoding=\"async\">\n                </picture>\n') WHERE name = 'banner-interial-category-new' AND snippet NOT LIKE '%<picture>%';
